__NUXT_JSONP__("/sp/school-calendar", {data:[{details:{slug:"sp",pageTitle:"Calendario Escolar | Mentor Language Institute",pageDescription:"La fecha de inicio del programa varía según los estudiantes F1 o no F1.",title:"Calendario Escolar",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003EAmarillo\u003C\u002Ffont\u003E: Fecha de inicio de programa (Módulo)\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003EVerde\u003C\u002Ffont\u003E： No colegio (Diá festivo)"],schoolCalendar:{title:"Calendario Escolar (Fecha de inicio de programa)",description:["\u003Cspan class=\"ymarker\"\u003ELa fecha de inicio del programa varía según los estudiantes F1 o no F1.\u003C\u002Fspan\u003E"],lists:[{key:"Estudiantes no F1 quienes no tienen una visa de estudiante.",value:["Pueden empezar su programa cualquier Lunes.\u003Cbr\u003E Si el lunes es feriado, la fecha de inicio del programa será el martes de esa semana."]},{key:"Estudiantes F1 quienes tienen una Visa de estudiante (F)",value:["Puede comenzar en lunes específicos. (resaltado en amarillo en el calendario).","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"Preguntas frecuentes sobre las fechas de llegada a los EE. UU.",lists:[{key:"\u003Cb\u003EP: ¿Cuántos días antes de la fecha de inicio del programa puede un estudiante ingresar a los Estados Unidos? \u003C\u002Fb\u003E",value:["R: MLI no requiere que nuestros estudiantes vengan a los Estados Unidos con un número específico de días de anticipación. Sin embargo, nuestros estudiantes generalmente ingresan a los EE. UU. 1 o 2 días antes de las fechas de inicio de sus programas."],note:"Nota: Los estudiantes internacionales pueden ingresar a los EE. UU. 30 días antes de la fecha de inicio de su programa."},{key:"\u003Cb\u003EP: ¿Es posible mudarse al alojamiento antes de la fecha de inicio del programa? \u003C\u002Fb\u003E",value:["R: Si. Podemos organizar la fecha de mudanza de tu alojamiento en cualquier fecha.\u003Cbr \u002F\u003ESi tienes otras preguntas, por favor no dudes en consultarnos."]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Fsp",extension:".json",createdAt:"2026-10-22T16:31:30.894Z",updatedAt:"2026-04-24T11:47:24.344Z"}}],fetch:{},mutations:void 0});